import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 1.6, 0);

  // Design token for accent color
  const accentColor = '#ff2a38';

  // Badge plane geometry and material
  const badgeGeometry = new THREE.PlaneGeometry(0.8, 0.3);
  const badgeTexture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  badgeTexture.colorSpace = THREE.SRGBColorSpace;

  const badgeMaterial = new THREE.MeshBasicNodeMaterial({
    map: badgeTexture,
    transparent: true
  });

  const badgeMesh = new THREE.Mesh(badgeGeometry, badgeMaterial);
  group.add(badgeMesh);

  // Accent edge border with emissive glow
  const edgeGeometry = new THREE.PlaneGeometry(0.84, 0.34);
  const edgeMaterial = new THREE.MeshBasicMaterial({
    color: accentColor,
    emissive: accentColor,
    emissiveIntensity: 0.3,
    transparent: true,
    opacity: 0.6,
    side: THREE.BackSide
  });
  const edgeMesh = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.z = -0.001;
  group.add(edgeMesh);

  // Animation timeline references
  let hoverTimeline = null;
  let clickTimeline = null;

  // Event handlers
  group.userData.handlers = {};

  // Hover: rise-in preset (y +0.15, power3.out, 0.7s)
  group.userData.handlers.hover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: 1.75,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Unhover: return to original position
  group.userData.handlers.unhover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: 1.6,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click: press-down effect (scale 0.97, 120ms, back.out) + event emission
  group.userData.handlers.click = () => {
    if (clickTimeline) clickTimeline.kill();
    clickTimeline = gsap.timeline();

    clickTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    });

    clickTimeline.to(group.scale, {
      x: 1,
      y: 1,
      duration: 0.12,
      ease: 'back.out'
    }, 0.1);

    // Emit hub-collection.select event
    if (config.onEvent) {
      config.onEvent('hub-collection.select');
    }
  };

  // Focus: enhance accent edge with increased glow
  group.userData.handlers.focus = () => {
    gsap.to(edgeMaterial, {
      emissiveIntensity: 0.7,
      opacity: 1,
      duration: 0.3,
      ease: 'power2.out'
    });
  };

  // Blur: reduce accent edge to default state
  group.userData.handlers.blur = () => {
    gsap.to(edgeMaterial, {
      emissiveIntensity: 0.3,
      opacity: 0.6,
      duration: 0.3,
      ease: 'power2.out'
    });
  };

  // Resource cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMaterial);

    badgeGeometry.dispose();
    edgeGeometry.dispose();
    badgeMaterial.dispose();
    edgeMaterial.dispose();
    badgeTexture.dispose();
  };

  return group;
}
